8	/**
9	 * Groups owners by city, comparing city names case-insensitively. Used both to size a
10	 * city's per-city customer-code sequence ({@link AssignCustomerCode}) and to enforce the
11	 * per-city capacity limit ({@link EnsureCityCapacity}).
12	 */
13	final class Cities {
14	
15	    private Cities() {
16	    }
17	
18	    /** How many existing owners live in the given city (case-insensitive match). */
19	    static long countIn(OwnerRepository repository, String city) {
20	        String key = cityKey(city);
21	        long count = 0;
22	        for (Owner existing : repository.findAll()) {
23	            if (key.equals(cityKey(existing.getCity()))) {
24	                count++;
25	            }
26	        }
27	        return count;
28	    }
29	
30	    /** Case-folded city name, so trivial casing differences still group together. */
31	    static String cityKey(String city) {
32	        return city == null ? "" : city.toLowerCase(Locale.ROOT);
33	    }
34	}
