3	import java.util.Map;
4	
5	/**
6	 * Shared telephone normalization for the owner pipelines: convert a raw telephone to
7	 * E.164 form. Spaces, dashes and brackets are stripped; a number that already carries
8	 * a leading {@code '+'} keeps its country code, otherwise Australian country code
9	 * {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the
10	 * national digits. The result is a {@code '+'} followed by 8 to 15 digits.
11	 *
12	 * <p>The national-number length must also match the country code: {@code '+61'}
13	 * (Australia) requires 9 national digits and {@code '+1'} (NANP) requires 10. A number
14	 * whose national part is the wrong length for its country is not valid E.164 here.
15	 *
16	 * <p>Used by {@link NormalizeOwnerTelephone}, which rejects a number that cannot form
17	 * valid E.164 and stores the normalized value, so every owner's telephone is canonical
18	 * before it becomes part of the owner's identity key.
19	 */
20	final class TelephoneNormalizer {
21	
22	    /** Country code -> the exact number of national digits E.164 requires for it. */
23	    private static final Map<String, Integer> NATIONAL_LENGTHS = Map.of("61", 9, "1", 10);
24	
25	    private TelephoneNormalizer() {
26	    }
27	
28	    /**
29	     * @return the E.164 representation of {@code telephone}, or {@code null} when it
30	     *         cannot form a valid E.164 number.
31	     */
32	    static String toE164(String telephone) {
33	        if (telephone == null) {
34	            return null;
35	        }
36	        String cleaned = telephone.replaceAll("[\\s()-]", "");
37	        String digits;
38	        if (cleaned.startsWith("+")) {
39	            digits = cleaned.substring(1);
40	        }
41	        else {
42	            if (cleaned.startsWith("0")) {
43	                cleaned = cleaned.substring(1);
44	            }
45	            digits = "61" + cleaned;
46	        }
47	        if (!digits.matches("[0-9]{8,15}") || !hasValidNationalLength(digits)) {
48	            return null;
49	        }
50	        return "+" + digits;
51	    }
52	
53	    /**
54	     * @return whether the national digits following a recognised country code have the
55	     *         length that code requires. Unrecognised country codes are left to the
56	     *         general 8-to-15-digit E.164 shape check.
57	     */
58	    private static boolean hasValidNationalLength(String digits) {
59	        String code = countryCode(digits);
60	        if (code == null) {
61	            return true;
62	        }
63	        return digits.length() - code.length() == NATIONAL_LENGTHS.get(code);
64	    }
65	
66	    /** The longest recognised country code that {@code digits} begins with, or null. */
67	    private static String countryCode(String digits) {
68	        String match = null;
69	        for (String code : NATIONAL_LENGTHS.keySet()) {
70	            if (digits.startsWith(code) && (match == null || code.length() > match.length())) {
71	                match = code;
72	            }
73	        }
74	        return match;
75	    }
76	}
