1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.ArrayList;
7	import java.util.List;
8	import java.util.Locale;
9	
10	import org.springframework.samples.petclinic.model.Owner;
11	import org.springframework.samples.petclinic.repository.OwnerRepository;
12	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
13	
14	/**
15	 * Identifies the owners that make up a household — those sharing a last name (compared
16	 * case-insensitively with collapsed whitespace) and a normalized address (see
17	 * {@link AddressNormalizer}). Used both to derive an owner's identity key
18	 * ({@link EnsureUniqueIdentity}) and to group knowing house-mates under a shared, stable
19	 * household id ({@link AssignHousehold}).
20	 */
21	final class Households {
22	
23	    private Households() {
24	    }
25	
26	    /**
27	     * The household id a create request would resolve to: the shared id for its last name
28	     * and address when it opts in with {@code sharesHousehold=true} and existing owners are
29	     * already at that household, otherwise null. Mirrors what {@link AssignHousehold} would
30	     * assign, so the identity check compares the candidate against the same id.
31	     */
32	    static String resolveHouseholdId(OwnerRepository repository, OwnerFieldsDto request) {
33	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
34	            return null;
35	        }
36	        if (membersAt(repository, request.getLastName(), request.getAddress()).isEmpty()) {
37	            return null;
38	        }
39	        return householdId(request.getLastName(), request.getAddress());
40	    }
41	
42	    /** Existing owners whose last name and address match the given household. */
43	    static List<Owner> membersAt(OwnerRepository repository, String lastName, String address) {
44	        String key = key(lastName, address);
45	        List<Owner> members = new ArrayList<>();
46	        for (Owner owner : repository.findAll()) {
47	            if (key.equals(key(owner.getLastName(), owner.getAddress()))) {
48	                members.add(owner);
49	            }
50	        }
51	        return members;
52	    }
53	
54	    /** How many existing owners already carry the given household id (0 when it is null). */
55	    static int memberCount(OwnerRepository repository, String householdId) {
56	        if (householdId == null) {
57	            return 0;
58	        }
59	        int count = 0;
60	        for (Owner owner : repository.findAll()) {
61	            if (householdId.equals(owner.getHouseholdId())) {
62	                count++;
63	            }
64	        }
65	        return count;
66	    }
67	
68	    /**
69	     * A stable identifier for the household with the given last name and address. Derived
70	     * from the normalized key, so every member of the same household resolves to the same
71	     * value regardless of when they are created.
72	     */
73	    static String householdId(String lastName, String address) {
74	        return "HH-" + sha256Hex(key(lastName, address)).substring(0, 24).toUpperCase(Locale.ROOT);
75	    }
76	
77	    /** The normalized last name and address joined into a single household key. */
78	    private static String key(String lastName, String address) {
79	        return normalizeName(lastName) + '\n' + AddressNormalizer.normalize(address);
80	    }
81	
82	    /** Case-fold and collapse whitespace so trivial spacing/casing differences still match. */
83	    private static String normalizeName(String value) {
84	        return value == null ? "" : value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
85	    }
86	
87	    private static String sha256Hex(String value) {
88	        try {
89	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
90	            StringBuilder hex = new StringBuilder(digest.length * 2);
91	            for (byte b : digest) {
92	                hex.append(String.format("%02x", b));
93	            }
94	            return hex.toString();
95	        }
96	        catch (NoSuchAlgorithmException ex) {
97	            throw new IllegalStateException("SHA-256 not available", ex);
98	        }
99	    }
100	}
