8	/**
9	 * Stamps a newly built owner with the effective registration date resolved by
10	 * {@link ResolveRegistrationDate}. Runs after {@link BuildOwner} and mutates the built
11	 * owner in place, overwriting whatever date the request body mapped in, so the owner is
12	 * stored and returned with the adjusted business day and later steps (e.g.
13	 * {@link AssignMembershipNumber}) derive their values from it.
14	 */
15	public class ApplyRegistrationDate {
16	
17	    public void service(@Val Owner owner, @Val LocalDate registrationDate) {
18	        owner.setRegistrationDate(registrationDate);
19	    }
20	}
