package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Groups owners by city, comparing city names case-insensitively. Used both to size a
 * city's per-city customer-code sequence ({@link AssignCustomerCode}) and to enforce the
 * per-city capacity limit ({@link EnsureCityCapacity}).
 */
final class Cities {

    private Cities() {
    }

    /** How many existing owners live in the given city (case-insensitive match). */
    static long countIn(OwnerRepository repository, String city) {
        String key = cityKey(city);
        long count = 0;
        for (Owner existing : repository.findAll()) {
            if (key.equals(cityKey(existing.getCity()))) {
                count++;
            }
        }
        return count;
    }

    /** Case-folded city name, so trivial casing differences still group together. */
    static String cityKey(String city) {
        return city == null ? "" : city.toLowerCase(Locale.ROOT);
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Assigns a newly built owner its {@code membershipNumber}, formatted
 * {@code <customerCode>-M<YY>} where YY is the last two digits of the owner's
 * registration date year (e.g. {@code LON-SMI-0007-M26}). Runs after
 * {@link AssignCustomerCode} and {@link ApplyRegistrationDate} so both inputs are
 * set — the year segment therefore uses the adjusted business day — and before
 * {@link SaveOwner}, mutating the built owner in place so the number is stored and
 * returned with the owner.
 */
public class AssignMembershipNumber {

    public void service(@Val Owner owner) {
        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
    }
}

